1074,1074,european_football_2,simple,1,correct,,0,4,210,1,,Match.`home_team_api_id`; Match.`home_team_goal`; Team.`team_api_id`; Team.`team_short_name`,List all the short name of the football team that had a home team goal of 10?,short name of the football team refers to team_short_name; home team goal refers to home_team_goal; home_team_goal = 10;,SELECT t1.team_short_name FROM Team AS t1 INNER JOIN Match AS t2 ON t1.team_api_id = t2.home_team_api_id WHERE t2.home_team_goal = 10,SELECT T2.team_short_name FROM Match AS T1 INNER JOIN Team AS T2 ON T1.home_team_api_id = T2.team_api_id WHERE T1.home_team_goal = 10;
1075,1075,european_football_2,moderate,0,generation_error_or_sql_logic,,0,5,210,1,,Player.`player_api_id`; Player.`player_name`; Player_Attributes.`balance`; Player_Attributes.`player_api_id`; Player_Attributes.`potential`,List all the football player with the highest balance score and potential score of 61.,balance score refers to balance; highest balance score refers to MAX(balance); potential score refers to potential; potential = 61;,SELECT t1.player_name FROM Player AS t1 INNER JOIN Player_Attributes AS t2 ON t1.player_api_id = t2.player_api_id WHERE t2.potential = '61' ORDER BY t2.balance DESC LIMIT 1,SELECT T1.player_name FROM Player AS T1 INNER JOIN Player_Attributes AS T2 ON T1.player_api_id = T2.player_api_id WHERE T2.potential = 61 AND T2.balance = (SELECT MAX(balance) FROM Player_Attributes)
